"""Count exact XYZ directly from raw selections, broken down by predeclared scene blocks."""
from pathlib import Path
import json,hashlib
from collections import Counter
ROOT=Path(__file__).resolve().parent
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
manifest=read(ROOT/'coverage-manifest.json');rows={r['id']:r for r in manifest['rows']}
frames={f['id']:f for f in read(ROOT/'development-corpus.json')['frames']}
inputs={r['id']:r for r in read(ROOT/'replay-inputs.json')['inputs']}
all_summary=[];wrong=[];evidence=[]
def summarize(model,mode,predictions,profile):
    assert len(predictions)==329
    counts={}
    for p in predictions:
        fid=p['id'].split('@')[0];f=frames[fid];selected=p.get('selected')
        for group in ['all']+([rows[fid]['sceneGroup']] if f['state']=='present' else []):
            c=counts.setdefault(group,Counter());c['frames']+=1
            if f['state']=='present':
                c['present']+=1
                if selected is None:c['miss']+=1
                elif all(selected[k]==f['expected'][k] for k in 'xyz'):c['correct']+=1
                else:
                    c['wrong']+=1
                    c['signErrors']+=any(selected[k] and f['expected'][k] and (selected[k]<0)!=(f['expected'][k]<0) for k in 'xyz')
            elif f['state']=='absent':c['absent']+=1;c['falsePositives']+=selected is not None
            else:c['unknown']+=1
        if (f['state']=='present' and selected is not None and not all(selected[k]==f['expected'][k] for k in 'xyz')) or (f['state']=='absent' and selected is not None):
            wrong.append({'model':model,'mode':mode,'profile':profile,'id':fid,'expected':f['expected'],'selected':selected,'rawText':p.get('rawText')})
    for group,c in counts.items():
        out={k:c[k] for k in ['frames','present','correct','wrong','miss','signErrors','absent','falsePositives','unknown']}
        assert out['correct']+out['wrong']+out['miss']==out['present']
        all_summary.append({'model':model,'mode':mode,'profile':profile,'group':group,**out})

for model in ['initial','previous','coverage-only','coverage-positive']:
    path=ROOT/f'replay-{model}.json'
    if not path.exists():continue
    payload=read(path);evidence.append({'model':model,'path':str(path),'sha256':sha(path)})
    for mode,predictions in payload['pipelines'].items():
        assert {p['id'] for p in predictions}==set(inputs)
        for p in predictions:assert p['pixelDigest']==inputs[p['id']]['pixelDigest']
        summarize(model,mode,predictions,'readout-line')
old=Path(r'C:\Dcode\WWMAP-TOOLS\out\coordinate-minimap-check\ocr-full-session')
yolo=read(old/'yolo.json');yi=[i for i in read(old/'inputs.json')['inputs'] if i['sourceId'] in frames and i['profile']=='upstream-band']
yidx={i['id']:i for i in yi};yp=[p for p in yolo['results'] if p['id'] in yidx];assert len(yp)==329
for p in yp:
    item=yidx[p['id']];assert p['pixelDigest']==item['pixelDigest']
    assert item['sourceSHA256']==frames[item['sourceId']]['captureSHA256']
    assert sha(Path(item['image']))==item['cropSHA256']
summarize('yolo','yolo',yp,'upstream-band')
evidence.append({'model':'yolo','path':str(old/'yolo.json'),'sha256':sha(old/'yolo.json')})
report={'scope':'180 blocked same-session development XYZ;141 absent;8 unknown. Neither untouched nor independent acceptance.',
    'previousModelTrainingOverlap':sum(r['split']=='development' and int(r['id'].rsplit('-',1)[1])<=899 for r in rows.values() if not r['historical']),
    'previousModelComparisonIsBiased':True,'thresholdChanged':False,'productionChanged':False,
    'manifestSHA256':sha(ROOT/'coverage-manifest.json'),'inputsSHA256':sha(ROOT/'replay-inputs.json'),
    'summary':all_summary,'wrongCases':wrong,'sourceEvidence':evidence}
(ROOT/'coverage-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for s in all_summary:
    if s['mode'] in ['ppocr-contrast-clock','ppocr-corroborated-clock','yolo']:
        print(s['model'],s['mode'],s['group'],s['correct'],s['wrong'],s['miss'],'FP',s['falsePositives'],flush=True)
